#!/usr/bin/env deno run --allow-read --allow-write

/**
 * Generates mock .svg.ts files and icon-exports.deno.ts for all SVG imports
 * This allows Deno tests to run without needing to handle actual SVG files
 */

import { dirname, join } from "jsr:@std/path";

const __dirname = dirname(new URL(import.meta.url).pathname);
const iconExportsFilePath = join(__dirname, "../icon-exports.ts");
const mockSvgDir = join(__dirname, "mock-svg-dir");
const repoRoot = join(__dirname, "../../..");
const scanRoots = [
  join(repoRoot, "tento/tento-ui-js"),
  join(repoRoot, "tento/tento-lona-js/sheets-ui"),
  join(repoRoot, "so_lona"),
];

const mockSvgContent = `const MOCK_SVG = \`<svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor"></svg>\`;
export default MOCK_SVG;
`;

async function generateMockSvgs() {
  const iconExportsContent = await Deno.readTextFile(iconExportsFilePath);

  // Extract all SVG import paths and icon names using regex
  const importRegex = /export \{ default as (\w+) \} from ["']@(?:yuzu\/ui|tento-ui)\/icons\/(.+\.svg)["'];/g;
  const matches = [...iconExportsContent.matchAll(importRegex)];
  const svgPaths = new Set(matches.map((match) => match[2]));

  for (const root of scanRoots) {
    for await (const filePath of walkTsFiles(root)) {
      const content = await Deno.readTextFile(filePath);
      const directImportRegex = /@(?:yuzu\/ui|tento-ui)\/icons\/([^"']+\.svg)/g;
      for (const match of content.matchAll(directImportRegex)) {
        svgPaths.add(match[1]);
      }
    }
  }

  console.log(`Found ${svgPaths.size} SVG imports`);

  const iconNames: string[] = [];

  // Generate individual .svg.ts mock files
  for (const svgPath of [...svgPaths].sort()) {
    const mockFilePath = `${mockSvgDir}/${svgPath}.ts`;

    // Create directory structure if needed
    const dirPath = mockFilePath.substring(0, mockFilePath.lastIndexOf('/'));
    try {
      await Deno.mkdir(dirPath, { recursive: true });
    } catch (e) {
      // Directory might already exist, ignore
    }

    // Write mock file
    await Deno.writeTextFile(mockFilePath, mockSvgContent);
    console.log(`Created: ${mockFilePath}`);
  }

  for (const match of matches) {
    iconNames.push(match[1]);
  }

  // Generate icon-exports.deno.ts that re-exports all icons as mocks
  const iconExportsDenoDtsPath = join(__dirname, "../icon-exports.deno.ts");
  const iconExports = iconNames.map(name => `export const ${name} = MOCK_SVG;`).join('\n');

  const iconExportsDenoDtsContent = `// Auto-generated mock icon exports for Deno tests
// This file is generated by icons/generate-mock-svgs.deno.ts

const MOCK_SVG = \`<svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor"></svg>\`;

${iconExports}

// Re-export constant string icons
export const EmptyIcon = MOCK_SVG;
export const TEMP_CALENDAR_ICON = MOCK_SVG;
`;

  await Deno.writeTextFile(iconExportsDenoDtsPath, iconExportsDenoDtsContent);
  console.log(`\nCreated: ${iconExportsDenoDtsPath}`);
  console.log(`Generated ${matches.length} mock SVG files in ${mockSvgDir}`);
}

async function* walkTsFiles(root: string): AsyncGenerator<string> {
  let entries: Deno.DirEntry[];
  try {
    entries = [];
    for await (const entry of Deno.readDir(root)) {
      entries.push(entry);
    }
  } catch {
    return;
  }

  for (const entry of entries) {
    if (entry.name === "mock-svg-dir") continue;
    if (entry.name === "node_modules") continue;
    const path = join(root, entry.name);
    if (entry.isDirectory) {
      yield* walkTsFiles(path);
      continue;
    }
    if (entry.isFile && path.endsWith(".ts")) {
      yield path;
    }
  }
}

await generateMockSvgs();
